// Parse Meta WhatsApp Cloud API inbound payload.
const body = $input.first().json.body || {};
const entry = (body.entry && body.entry[0]) || {};
const change = (entry.changes && entry.changes[0]) || {};
const value = change.value || {};
if (value.statuses) {
  return [{ json: { _action: 'ignore', reason: 'status_event' } }];
}
const msg = value.messages && value.messages[0];
if (!msg) {
  return [{ json: { _action: 'ignore', reason: 'no_message' } }];
}
const phone = msg.from || '';
let text = '';
let interactive_id = '';
if (msg.type === 'text' && msg.text) { text = msg.text.body || ''; }
else if (msg.type === 'button' && msg.button) {
  text = msg.button.text || '';
  interactive_id = msg.button.payload || '';
}
else if (msg.type === 'interactive' && msg.interactive) {
  const it = msg.interactive;
  text = (it.button_reply && it.button_reply.title) || (it.list_reply && it.list_reply.title) || '';
  interactive_id = (it.button_reply && it.button_reply.id) || (it.list_reply && it.list_reply.id) || '';
} else {
  return [{ json: { _action: 'ignore', reason: 'unsupported_message_type' } }];
}
const contact = (value.contacts && value.contacts[0]) || {};
const pushName = (contact.profile && contact.profile.name) || '';
const messageId = msg.id || '';
const timestamp = msg.timestamp ? parseInt(msg.timestamp, 10) : Math.floor(Date.now() / 1000);
return [{ json: { _action: 'process', phone, text: String(text).trim(), interactive_id: String(interactive_id).trim(), pushName, messageId, timestamp, remoteJid: phone } }];

// Determine routing based on dedup + classification results.
// Input: the parsed message from 'Parse Evolution Payload' + DB classification.

const parsed = $('Parse Evolution Payload').first().json;
const db = $input.first().json;

// If message was already processed (dedup), ignore
if (!db.new_message_id && db.new_message_id !== 0) {
  return [{ json: { route: 'ignore', reason: 'duplicate_message' } }];
}

const phone = parsed.phone;
const text = parsed.text;
const pushName = parsed.pushName;
const messageId = parsed.messageId;

// Check if sender is an agent
if (db.is_agent) {
  // Prefer the routing-v2 quick-reply payload over human-visible text.
  const claimMatch = String(parsed.interactive_id || '').match(/^claim:(\d+):(owner|primary_guard|backup_guard)$/);
  if (claimMatch) {
    const opportunityId = Number(claimMatch[1]);
    if (!Number.isSafeInteger(opportunityId) || opportunityId <= 0) {
      return [{ json: { route: 'ignore', reason: 'invalid_v2_claim_payload' } }];
    }
    return [{ json: { route: 'agent_claim', agent_id: db.agent_id, agent_name: db.agent_name, agent_phone: phone, opportunity_id: opportunityId, routing_tier: claimMatch[2], raw_message: parsed.interactive_id, messageId } }];
  }
  // Approved text-template fallback while the quick-reply template is pending approval.
  const textClaimMatch = String(text || '').trim().match(/^TOMO-V2-(\d+)-(O|P|B)$/i);
  if (textClaimMatch) {
    const opportunityId = Number(textClaimMatch[1]);
    if (!Number.isSafeInteger(opportunityId) || opportunityId <= 0) {
      return [{ json: { route: 'ignore', reason: 'invalid_v2_claim_text' } }];
    }
    const tierByCode = { O: 'owner', P: 'primary_guard', B: 'backup_guard' };
    return [{ json: { route: 'agent_claim', agent_id: db.agent_id, agent_name: db.agent_name, agent_phone: phone, opportunity_id: opportunityId, routing_tier: tierByCode[textClaimMatch[2].toUpperCase()], raw_message: text, messageId } }];
  }
  // Preserve the legacy TOMO claim while older auctions drain.

  const tomoMatch = text.match(/^TOMO-([A-Z0-9]{4})$/i);
  if (tomoMatch) {
    return [{
      json: {
        route: 'agent_claim',
        agent_id: db.agent_id,
        agent_name: db.agent_name,
        agent_phone: phone,
        short_code: tomoMatch[1].toUpperCase(),
        raw_message: text,
        messageId
      }
    }];
  }
  // Agent sent a non-TOMO message -> follow-up reply (WF15 decides relevance)
  return [{ json: { route: 'agent_followup_reply', agent_id: db.agent_id, agent_name: db.agent_name, agent_phone: phone, text, messageId } }];
}

// Not an agent - check conversation status
if (!db.conversation_id) {
  // New lead - no conversation exists
  return [{
    json: {
      route: 'new_lead',
      phone,
      pushName,
      text,
      messageId
    }
  }];
}

// Existing conversation - route by mode
const mode = db.conv_mode;
if (mode === 'ai') {
  return [{
    json: {
      route: 'ai_conversation',
      conversation_id: db.conversation_id,
      phone,
      pushName,
      text,
      messageId,
      current_property: db.current_property,
      assigned_agent_id: db.assigned_agent_id
    }
  }];
}

if (mode === 'human') {
  return [{
    json: {
      route: 'human_forward',
      conversation_id: db.conversation_id,
      phone,
      pushName,
      text,
      messageId,
      assigned_agent_id: db.assigned_agent_id,
      assigned_agent_phone: db.assigned_agent_phone
    }
  }];
}

if (mode === 'pending_assignment') {
  return [{
    json: {
      route: 'pending',
      conversation_id: db.conversation_id,
      phone,
      pushName,
      text,
      messageId
    }
  }];
}

// Fallback
return [{ json: { route: 'ignore', reason: 'unknown_mode' } }];

// Forward lead message to assigned agent via Evolution.
// In human mode, the bot acts as a relay.
const data = $input.first().json;

const forwardBody = [
  `Mensaje de ${data.pushName || 'Lead'} (${data.phone}):`,
  ``,
  data.text
].join('\n');

return [{
  json: {
    number: data.assigned_agent_phone,
    text: forwardBody,
    conversation_id: data.conversation_id,
    phone: data.phone
  }
}];

